<?php
namespace App\Services;
use App\Models\{BookingMobil,Mobil};
use Illuminate\Support\Facades\{DB,Schema};
use RuntimeException;
class BookingMobilService {
 public function actorPetugasId(?int $userId): ?int{return DB::table('petugas')->where('id_user',$userId)->value('id_petugas') ?: DB::table('petugas')->where('status','aktif')->value('id_petugas');}
 private function code():string{$code='BKG-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(3)));while(BookingMobil::where('kode_booking',$code)->exists())$code='BKG-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(3)));return $code;}
 public function create(int $customerId,int $mobilId,?string $note):BookingMobil{return DB::transaction(function()use($customerId,$mobilId,$note){$car=Mobil::lockForUpdate()->findOrFail($mobilId);$inventory=app(VehicleInventoryService::class)->find($car);if($inventory){$available=(int)$inventory->stock_total-(int)$inventory->sold_units-app(VehicleInventoryService::class)->reserveCount($car);if($available<1)throw new RuntimeException('Stok kendaraan tidak tersedia untuk booking.');}elseif($car->status!=='tersedia')throw new RuntimeException('Unit kendaraan tidak tersedia untuk booking.');$b=new BookingMobil();$b->forceFill(['kode_booking'=>$this->code(),'id_pelanggan'=>$customerId,'id_mobil'=>$mobilId,'tanggal_booking'=>now(),'tanggal_expired'=>now()->addDays(3),'catatan'=>$note,'status'=>'menunggu']);$b->save();return $b;});}
 public function confirm(int $id,int $petugasId):void{DB::transaction(function()use($id,$petugasId){$b=BookingMobil::lockForUpdate()->findOrFail($id);if($b->status!=='menunggu')throw new RuntimeException('Booking tidak berada pada status menunggu.');$car=Mobil::lockForUpdate()->findOrFail($b->id_mobil);$inventory=app(VehicleInventoryService::class)->find($car);if($inventory&&((int)$inventory->stock_total-(int)$inventory->sold_units-app(VehicleInventoryService::class)->reserveCount($car)+1)<1)throw new RuntimeException('Stok kendaraan tidak tersedia untuk dikonfirmasi.');if(!$inventory&&$car->status!=='tersedia')throw new RuntimeException('Unit kendaraan sudah tidak tersedia untuk dikonfirmasi.');$b->forceFill(['status'=>'dikonfirmasi','id_petugas_konfirmasi'=>$petugasId])->save();if(!$inventory)DB::table('mobil')->where('id_mobil',$car->id_mobil)->where('status','tersedia')->update(['status'=>'dibooking']);});}
 public function cancel(int $id,?int $customerId=null):void{DB::transaction(function()use($id,$customerId){$q=BookingMobil::whereKey($id);if($customerId!==null)$q->where('id_pelanggan',$customerId);$b=$q->lockForUpdate()->first();if(!$b||!in_array($b->status,['menunggu','dikonfirmasi'],true))throw new RuntimeException('Booking tidak dapat dibatalkan pada status ini.');$car=Mobil::lockForUpdate()->find($b->id_mobil);$b->forceFill(['status'=>'dibatalkan'])->save();$this->unlockIfSafe($car);});}
 public function complete(int $id):void{DB::transaction(function()use($id){$b=BookingMobil::lockForUpdate()->findOrFail($id);if($b->status!=='dikonfirmasi')throw new RuntimeException('Status booking tidak dapat diselesaikan.');$b->forceFill(['status'=>'selesai'])->save();});}
 public function expire():int{$count=0;BookingMobil::whereNotNull('tanggal_expired')->where('tanggal_expired','<',now())->whereIn('status',['menunggu','dikonfirmasi'])->pluck('id_booking')->each(function($id)use(&$count){try{DB::transaction(function()use($id,&$count){$b=BookingMobil::lockForUpdate()->find($id);if(!$b||!in_array($b->status,['menunggu','dikonfirmasi'],true))return;$car=Mobil::lockForUpdate()->find($b->id_mobil);$b->forceFill(['status'=>'kadaluarsa'])->save();$this->unlockIfSafe($car);$count++;});}catch(\Throwable $e){}});return $count;}
 private function unlockIfSafe(?Mobil $car):void{if(!$car||app(VehicleInventoryService::class)->find($car)||$car->status!=='dibooking')return;$hasSale=Schema::hasTable('penjualan_mobil')&&DB::table('penjualan_mobil')->where('id_mobil',$car->id_mobil)->where('status','<>','dibatalkan')->exists();if(!$hasSale)DB::table('mobil')->where('id_mobil',$car->id_mobil)->where('status','dibooking')->update(['status'=>'tersedia']);}
}
